  return function(){
    h=Math.imul(h^(h>>>16),2246822507);
    h=Math.imul(h^(h>>>13),3266489909);
    h^=h>>>16;
    return h>>>0;
  };
}
function mulberry32(seed){
  var a=seed>>>0;
  return function(){
    a|=0; a=(a+0x6D2B79F5)|0;
    var t=Math.imul(a^(a>>>15),1|a);
    t=(t+Math.imul(t^(t>>>7),61|t))^t;
    return ((t^(t>>>14))>>>0)/4294967296;
  };
}
function sfc32(a,b,c,d){
  return function(){
    a>>>=0; b>>>=0; c>>>=0; d>>>=0;
    var t=(a+b)|0;
    a=b^(b>>>9);
    b=(c+(c<<3))|0;
    c=(c<<21)|(c>>>11);
    d=(d+1)|0;
    t=(t+d)|0;
    c=(c+t)|0;
    return (t>>>0)/4294967296;
  };
}
function xoshiro128ss(a,b,c,d){
  return function(){
    var t=b<<9, r=Math.imul(b,5);
    r=((r<<7)|(r>>>25))>>>0;
    r=Math.imul(r,9)>>>0;
    c^=a; d^=b; b^=c; a^=d; c^=t;
    d=(d<<11)|(d>>>21);
    return r/4294967296;
  };
}
function prngCreate(algo, seedStr){
  var h=seedHash(seedStr);
  if(algo==='mulberry32') return mulberry32(h());
  if(algo==='sfc32') return sfc32(h(),h(),h(),h());
  if(algo==='xoshiro128ss') return xoshiro128ss(h(),h(),h(),h());
  throw new Error('unknown algo: '+algo);
}
function prngSequence(algo, seedStr, n){
  var f=prngCreate(algo, seedStr), out=[];
  for(var i=0;i<n;i++) out.push(f());
  return out;
}
function prngIntRange(algo, seedStr, n, lo, hi){
